record.field:
{
  "type": "object",
  "properties": {
    "query": {"type": "string", "description": "Search keyword for lead or customer name"},
    "limit": {"type": "integer", "description": "Maximum number of leads to return", "default": 5}
  }
}

{
  "type": "object",
  "properties": {
    "lead_id": {"type": "integer", "description": "ID of the CRM lead to summarize"}
  },
  "required": ["lead_id"]
}

{
  "type": "object",
  "properties": {
    "name": {"type": "string", "description": "Opportunity title or prospect inquiry"},
    "partner_id": {"type": "integer", "description": "Optional customer partner ID"},
    "expected_revenue": {"type": "number", "description": "Expected deal amount"},
    "description": {"type": "string", "description": "Details or requirements"}
  },
  "required": ["name"]
}

{
  "type": "object",
  "properties": {
    "partner_name": {"type": "string", "description": "Customer name (e.g. Azure Interior, Deco Addict, or custom name)"},
    "partner_id": {"type": "integer", "description": "Optional customer Partner ID if known"},
    "lines": {
      "type": "array",
      "description": "List of products to add to quotation",
      "items": {
        "type": "object",
        "properties": {
          "product_name": {"type": "string", "description": "Product name or reference keyword"},
          "quantity": {"type": "number", "description": "Quantity to order", "default": 1},
          "price_unit": {"type": "number", "description": "Optional custom unit price"}
        },
        "required": ["product_name"]
      }
    }
  },
  "required": ["partner_name"]
}

{
  "type": "object",
  "properties": {
    "query": {"type": "string", "description": "Vendor name or PO reference (e.g. P00012, Vicky)"},
    "limit": {"type": "integer", "default": 5}
  }
}

{
  "type": "object",
  "properties": {
    "partner_name": {"type": "string", "description": "Vendor / Supplier name (e.g. Vicky, Azure Interior, Gemini Foods)"},
    "partner_id": {"type": "integer", "description": "Optional vendor Partner ID if known"},
    "lines": {
      "type": "array",
      "description": "List of products to purchase",
      "items": {
        "type": "object",
        "properties": {
          "product_name": {"type": "string", "description": "Product name (e.g. Tomato, Desk, Office Chair)"},
          "product_id": {"type": "integer", "description": "Optional Product ID"},
          "quantity": {"type": "number", "description": "Quantity to order (e.g. 20)"},
          "uom_name": {"type": "string", "description": "Unit of Measure (e.g. kg, Units, Hours)"},
          "price_unit": {"type": "number", "description": "Unit price (optional)"}
        },
        "required": ["quantity"]
      }
    },
    "notes": {"type": "string", "description": "Optional terms, notes, or special instructions"}
  },
  "required": ["partner_name"]
}

{
  "type": "object",
  "properties": {
    "res_model": {"type": "string", "description": "Target model (e.g. crm.lead, sale.order, res.partner)"},
    "res_id": {"type": "integer", "description": "Target record ID"},
    "summary": {"type": "string", "description": "Activity title / summary"},
    "note": {"type": "string", "description": "Details or agenda"},
    "date_deadline": {"type": "string", "description": "Deadline YYYY-MM-DD"}
  },
  "required": ["res_model", "res_id", "summary"]
}

{
  "type": "object",
  "properties": {
    "res_model": {"type": "string", "description": "Target model name"},
    "res_id": {"type": "integer", "description": "Target record ID"},
    "body": {"type": "string", "description": "Message HTML or text content"}
  },
  "required": ["res_model", "res_id", "body"]
}

{
  "type": "object",
  "properties": {
    "model": {"type": "string", "description": "Technical model name (e.g. account.move, stock.picking, purchase.order, hr.employee)"},
    "domain": {"type": "array", "description": "Odoo search domain list, e.g. [[\"state\", \"=\", \"draft\"]]", "items": {}},
    "fields": {"type": "array", "description": "List of field names to retrieve", "items": {"type": "string"}},
    "limit": {"type": "integer", "description": "Maximum number of records to return (default 10)", "default": 10},
    "order": {"type": "string", "description": "SQL sort order, e.g. 'id desc'"}
  },
  "required": ["model"]
}

{
  "type": "object",
  "properties": {
    "model": {"type": "string", "description": "Technical model name to create in (e.g. res.partner, purchase.order, project.task)"},
    "values": {"type": "object", "description": "Dictionary of field values to set on creation"}
  },
  "required": ["model", "values"]
}

{
  "type": "object",
  "properties": {
    "model": {"type": "string", "description": "Technical model name"},
    "id": {"type": "integer", "description": "ID of the record to update"},
    "values": {"type": "object", "description": "Dictionary of fields to update"}
  },
  "required": ["model", "id", "values"]
}

{
  "type": "object",
  "properties": {
    "model": {"type": "string", "description": "Technical model name"},
    "id": {"type": "integer", "description": "ID of the record to delete"}
  },
  "required": ["model", "id"]
}

{
  "type": "object",
  "properties": {
    "state": {"type": "string", "description": "Filter by state: 'installed', 'uninstalled', or 'to upgrade'"},
    "query": {"type": "string", "description": "Search keyword for app or module name"},
    "limit": {"type": "integer", "description": "Max modules to list", "default": 20}
  }
}

{
  "type": "object",
  "properties": {
    "name": {"type": "string", "description": "Descriptive name of the automation rule"},
    "model_name": {"type": "string", "description": "Target technical model (e.g. sale.order, crm.lead)"},
    "trigger": {"type": "string", "enum": ["on_create", "on_write", "on_create_or_write"], "description": "When this automation should trigger"}
  },
  "required": ["name", "model_name"]
}

{
  "type": "object",
  "properties": {
    "setting_names": {
      "type": "array",
      "items": {"type": "string"},
      "description": "List of setting names or search keywords to check (e.g. ['storage_locations', 'packages', 'multi_step_routes', 'variants'])"
    }
  },
  "required": ["setting_names"]
}

{
  "type": "object",
  "properties": {
    "settings": {
      "type": "object",
      "description": "Key-value mapping of settings to update (e.g. {'group_stock_multi_locations': false} or {'storage_locations': true})"
    }
  },
  "required": ["settings"]
}
